import { Product, ProductOptionsKeys } from './product';
import { ProductMedia } from './product-media';
import { ProductImage } from './product-image';
import { UnitPriceMeasurement } from './unit-price-measurement';
export type ProductVariantOptionMap<TKeys extends ProductOptionsKeys[number] = string> = Record<TKeys, string>;
export type ProductVariantOptions = [
] | [value1: string] | [value1: string, value2: string] | [value1: string, value2: string, value3: string];
export type Address = {
    address1: string;
    address2: string;
    city: string;
    company: string;
    country: Record<string, unknown>;
    country_code: string;
    first_name: string;
    id: number;
    last_name: string;
    name: string;
    phone: string;
    province: string;
    province_code: string;
    street: string;
    summary: string;
    url: string;
    zip: string;
};
export type Location = {
    address: Address;
    id: number;
    latitude: number;
    longitude: number;
    metafields: Record<string, unknown>;
    name: string;
};
export type StoreAvailability = {
    available: boolean;
    location: Location;
    pick_up_enabled: boolean;
    pick_up_time: string;
};
export type ProductVariant<TOptions extends ProductVariantOptions = ProductVariantOptions> = {
    available: boolean;
    barcode: string;
    compare_at_price: number | null;
    featured_image: ProductImage | null;
    featured_media: ProductMedia | null;
    id: number;
    image: ProductImage;
    incoming: boolean;
    inventory_management: string;
    inventory_policy: string;
    inventory_quantity: number | string;
    matched: boolean;
    metafields: Record<string, unknown>;
    next_incoming_date: null | string;
    option1: null | string;
    option2: null | string;
    option3: null | string;
    options: TOptions;
    price: number;
    product: Product;
    quantity_rule: Record<string, unknown>;
    requires_selling_plan: boolean;
    requires_shipping: boolean;
    selected: boolean;
    selected_selling_plan_allocation: null | string;
    selling_plan_allocations: string[];
    sku: string;
    store_availabilities: StoreAvailability[];
    taxable: boolean;
    title: string;
    unit_price: number | null;
    unit_price_measurement: UnitPriceMeasurement | null;
    url: string;
    weight: number;
    weight_in_unit: number;
    weight_unit: string;
};
